"C:\\Program Files\\WindowsApps\\OpenAI.CodexPrimaryRuntime.v26-1104-2876-0_26.1104.2876.0_x64__3k8sg7r9htsxt\\dependencies\\native\\powershell\\pwsh.exe" -Command '$rates = @{}
foreach ($code in '"'PN09822PM','PN01273PM') {
    "'$series = Get-Content -Raw -LiteralPath "datos/$code.json" | ConvertFrom-Json
    $series.config.series | Select-Object name
    $matchesDec = @($series.periods | Where-Object { $_.name -match '"'"'^(Dic|Dec)[.-]?'"\\s*(2024|24)"'$'"' })
    if ("'$matchesDec.Count -ne 1) { throw "Periodo no identificado de forma unica en $code. Total de periodos: $($series.periods.Count)" }
    $rates[$code] = [decimal]::Parse($matchesDec[0].values[0], [cultureinfo]::InvariantCulture)
}
"Alimentos: $($rates['"'PN09822PM']) %\"
\"General: "'$($rates['"'PN01273PM']) %\"
\"Diferencia: "'$($rates['"'PN09822PM'] - "'$rates['"'PN01273PM']) pp\""

